{
  "name": "@zinn-dev/opencode",
  "version": "0.5.0",
  "type": "module",
  "description": "Experimental Zinn task inspector and desktop board summary for OpenCode.",
  "keywords": [
    "zinn",
    "opencode",
    "opencode-plugin",
    "tui",
    "desktop",
    "kanban",
    "task-management",
    "ai-agents",
    "developer-tools"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/yethranayeh/zinn.git",
    "directory": "integrations/opencode/inspector"
  },
  "bugs": {
    "url": "https://github.com/yethranayeh/zinn/issues"
  },
  "homepage": "https://zinn.sh/integrations/opencode/inspector",
  "exports": {
    ".": "./dist/index.js",
    "./tui": "./dist/tui.js",
    "./gui-experimental": "./dist/gui-experimental.cjs"
  },
  "files": [
    "dist"
  ],
  "peerDependencies": {
    "@opencode/plugin": ">=2.3.2 <3",
    "@opentui/core": ">=0.8.4 <0.9.0",
    "@opentui/solid": ">=0.8.4 <0.9.0",
    "effect": ">=4.0.1 <5",
    "solid-js": ">=1.9.0"
  },
  "peerDependenciesMeta": {
    "@opencode/plugin": {
      "optional": true
    },
    "@opentui/core": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    },
    "effect": {
      "optional": true
    }
  },
  "devDependencies": {
    "@babel/core": "7.29.7",
    "@babel/preset-typescript": "7.27.1",
    "@opencode/plugin": "2.2.0",
    "@opencode/theme": "2.2.0",
    "@opentui/core": "0.7.0",
    "@opentui/solid": "0.7.0",
    "babel-preset-solid": "1.9.12",
    "effect": "4.0.1",
    "solid-js": "^1.9.0",
    "vite": "7.3.7",
    "vite-plugin-solid": "2.11.14"
  },
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "build": "bun checks/build.mjs",
    "test": "bun run --cwd ../../.. test --timeout 120000 ./integrations/opencode/inspector/pkg ./integrations/opencode/inspector/tests",
    "typecheck": "bun ../../../scripts/typecheck.ts integrations/opencode/inspector",
    "test:package": "bun run --cwd ../../.. test --timeout 120000 ./integrations/opencode/inspector/tests/package.test.ts"
  }
}

import { Plugin } from "@opencode/plugin";
export default Plugin.define({
  id: "zinn",
  setup() {}
});
